import { type ReactNode, useEffect, useMemo, useRef, useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { useLocation, useRoute, Route, Switch, Router as WouterRouter, Link } from 'wouter';
import { BarChart3, Bell, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, ClipboardList, Download, FileText, FolderKanban, GraduationCap, LayoutDashboard, Menu, MessageSquare, Moon, MoreHorizontal, Pencil, Plus, Search, Settings, SlidersHorizontal, Sparkles, Sun, Trash2, TrendingUp, Upload, UserRound, Users, X, Mic, MicOff, Activity as ActivityIcon } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis } from 'recharts';
import { courses, departments, type Activity, type Assignment, type Attendance, type Event, type Exam, type Project, type Student, loadLocal, saveLocal, seedActivities, seedAssignments, seedAttendance, seedEvents, seedExams, seedProjects, seedStudents } from '@/lib/mock-data';

declare global {
  namespace JSX {
    interface IntrinsicAttributes { [key: string]: unknown; }
  }
}

const queryClient = new QueryClient();
const nav = [
  { href:'/dashboard', label:'Overview', icon:LayoutDashboard },
  { href:'/students', label:'Students', icon:Users },
  { href:'/attendance', label:'Attendance', icon:Check },
  { href:'/projects', label:'Projects', icon:FolderKanban },
  { href:'/assignments', label:'Assignments', icon:ClipboardList },
  { href:'/exams', label:'Exams & grades', icon:BookOpen },
  { href:'/timetable', label:'Timetable', icon:CalendarDays },
  { href:'/messages', label:'Messages', icon:MessageSquare },
  { href:'/events', label:'Events', icon:Sparkles },
  { href:'/reports', label:'Reports', icon:BarChart3 },
];
const utilityNav = [{ href:'/settings', label:'Settings', icon:Settings }];
const teal = '#2b847d';
const orange = '#e9945b';
const notify = (message: string) => window.dispatchEvent(new CustomEvent('edumanage-toast', { detail: message }));
function parseVoiceStudent(command: string): Partial<Student> {
  const text = command.replace(/^add\s+student\s*/i, '').trim();
  const courseMatch = text.match(/\b(B\.?Des|BCA|B\.?Tech|MCA)\b/i);
  const semesterMatch = text.match(/\b(?:semester|sem)\s*(\d+)\b/i);
  const name = text.replace(courseMatch?.[0] || '', '').replace(semesterMatch?.[0] || '', '').replace(/\s+/g, ' ').trim();
  return { name, course: courseMatch?.[0]?.replace('B.Des', 'B.Des') || 'BCA', semester: Number(semesterMatch?.[1] || 1) };
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Shell /></RoutedErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }

function Shell() {
  const [location, setLocation] = useLocation();
  const [drawer, setDrawer] = useState(false);
  const [palette, setPalette] = useState(false);
  const [notifications, setNotifications] = useState(false);
  const [dark, setDark] = useState(() => localStorage.getItem('edumanage-theme') === 'dark');
  const [query, setQuery] = useState('');
  const [students, setStudents] = useState<Student[]>(() => loadLocal('students', seedStudents));
  const [projects] = useState<Project[]>(() => loadLocal('projects', seedProjects));
  const [assignments] = useState<Assignment[]>(() => loadLocal('assignments', seedAssignments));
  const [exams] = useState<Exam[]>(() => loadLocal('exams', seedExams));
  const [activities] = useState<Activity[]>(seedActivities);
  const [listening, setListening] = useState(false);
  const [voiceDraft, setVoiceDraft] = useState('');
  const [toast, setToast] = useState('');
  const recognition = useRef<any>(null);
  useEffect(() => { document.documentElement.classList.toggle('dark', dark); localStorage.setItem('edumanage-theme', dark ? 'dark' : 'light'); }, [dark]);
  useEffect(() => { const listener = (e: KeyboardEvent) => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setPalette(true); } if (e.key === 'Escape') { setPalette(false); setNotifications(false); } }; window.addEventListener('keydown', listener); return () => window.removeEventListener('keydown', listener); }, []);
  const flash = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2300); };
  useEffect(() => { const handler = (event: globalThis.Event) => setToast((event as unknown as CustomEvent<string>).detail); window.addEventListener('edumanage-toast', handler); return () => window.removeEventListener('edumanage-toast', handler); }, []);
  const startVoice = () => {
    const Speech = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (!Speech) { flash('Voice input is unavailable here — try typing your command.'); setPalette(true); return; }
    if (listening) { recognition.current?.stop(); setListening(false); return; }
    const r = new Speech(); recognition.current = r; r.continuous = false; r.interimResults = false; r.lang = 'en-IN'; setListening(true);
    r.onresult = (e: any) => { const transcript = e.results[0][0].transcript; if (/^add\s+student/i.test(transcript)) { setVoiceDraft(transcript); saveLocal('voice-draft', parseVoiceStudent(transcript)); setLocation('/students'); setPalette(false); window.setTimeout(() => (document.querySelector('[data-testid="button-add-student"]') as HTMLButtonElement | null)?.click(), 120); } else { setQuery(transcript); setPalette(true); } setListening(false); };
    r.onerror = () => { setListening(false); flash('I couldn’t hear that. Try the typed command instead.'); };
    r.onend = () => setListening(false); r.start();
  };
  const quickResults = useMemo(() => {
    if (!query.trim()) return [];
    const q = query.toLowerCase();
    return [
      ...students.filter(s => `${s.name} ${s.course} ${s.department}`.toLowerCase().includes(q)).slice(0, 4).map(s => ({ label:s.name, sub:`${s.course} · Semester ${s.semester}`, href:`/students/${s.id}`, icon:Users })),
      ...projects.filter(p => `${p.name} ${p.student}`.toLowerCase().includes(q)).slice(0, 3).map(p => ({ label:p.name, sub:`Project · ${p.progress}% complete`, href:`/projects/${p.id}`, icon:FolderKanban })),
      ...assignments.filter(a => a.title.toLowerCase().includes(q)).slice(0, 2).map(a => ({ label:a.title, sub:`Assignment · ${a.course}`, href:'/assignments', icon:ClipboardList })),
      ...exams.filter(e => e.name.toLowerCase().includes(q)).slice(0, 2).map(e => ({ label:e.name, sub:`Exam · ${e.date}`, href:'/exams', icon:BookOpen })),
    ];
  }, [query, students, projects, assignments, exams]);
  const pageTitle = location === '/dashboard' || location === '/' ? 'Hi, Faseela, Welcome Back!' : nav.find(n => location.startsWith(n.href))?.label || (location.startsWith('/students/') ? 'Student profile' : location.startsWith('/projects/') ? 'Project detail' : 'Workspace');
  const updateStudents = (next: Student[]) => { setStudents(next); saveLocal('students', next); };
  return <div className="min-h-[100dvh] app-shell flex">
    <aside className={`fixed z-40 inset-y-0 left-0 w-[248px] bg-sidebar text-sidebar-foreground flex flex-col border-r border-sidebar-border transition-transform duration-300 lg:static lg:translate-x-0 ${drawer ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="h-[84px] flex items-center px-6 border-b border-sidebar-border"><div className="size-9 rounded-xl bg-sidebar-primary text-sidebar-primary-foreground flex items-center justify-center font-mono font-bold">E</div><div className="ml-3"><div className="font-bold tracking-tight text-[17px]">EduManage</div><div className="text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/50">Eastbridge University</div></div><button aria-label="Close navigation" data-testid="button-close-drawer" onClick={() => setDrawer(false)} className="ml-auto lg:hidden"><X size={18}/></button></div>
      <div className="px-3 pt-6 pb-3 text-[10px] tracking-[.18em] text-sidebar-foreground/40 uppercase">Command center</div>
      <nav className="px-3 space-y-1 flex-1">{nav.map(item => <NavItem key={item.href} {...item} current={location} onClick={() => setDrawer(false)} />)}</nav>
      <div className="px-3 pb-5 space-y-1"><div className="text-[10px] tracking-[.18em] text-sidebar-foreground/40 uppercase px-3 pb-2">Workspace</div>{utilityNav.map(item => <NavItem key={item.href} {...item} current={location} onClick={() => setDrawer(false)} />)}<div className="mt-5 p-3 rounded-2xl bg-sidebar-accent border border-sidebar-border"><div className="flex items-center gap-2 text-xs font-semibold"><span className="size-2 rounded-full bg-sidebar-primary animate-pulse"/> Spring term 2025</div><div className="text-[11px] text-sidebar-foreground/50 mt-1">Week 11 of 16</div><div className="h-1.5 bg-sidebar-foreground/10 rounded-full mt-3 overflow-hidden"><div className="h-full bg-sidebar-primary rounded-full w-[68%]"/></div></div></div>
    </aside>
    {drawer && <button aria-label="Close menu overlay" data-testid="button-overlay" onClick={() => setDrawer(false)} className="fixed inset-0 bg-black/25 z-30 lg:hidden"/>}
    <main className="min-w-0 flex-1 flex flex-col">
      <header className="h-[84px] px-4 sm:px-7 lg:px-10 flex items-center justify-between border-b border-border/70 bg-background/65 backdrop-blur-xl sticky top-0 z-20">
        <div className="flex items-center gap-3"><button aria-label="Open navigation" data-testid="button-open-drawer" onClick={() => setDrawer(true)} className="lg:hidden p-2 rounded-lg hover:bg-muted"><Menu size={20}/></button><div><div className="text-[11px] uppercase tracking-[.16em] text-muted-foreground font-semibold">Tuesday · 08 April 2025</div><h1 data-testid="text-page-title" className="text-xl sm:text-[23px] font-bold tracking-tight mt-0.5">{pageTitle}</h1></div></div>
        <div className="flex items-center gap-2 sm:gap-3"><button data-testid="button-command-palette" aria-label="Open command search" onClick={() => setPalette(true)} className="hidden sm:flex items-center gap-3 h-10 w-48 px-3 rounded-xl border border-border bg-card/70 text-muted-foreground text-sm hover:border-primary/50"><Search size={16}/><span>Search anything</span><kbd className="ml-auto font-mono text-[10px] bg-muted px-1.5 py-0.5 rounded">⌘K</kbd></button><button data-testid="button-mobile-search" aria-label="Search" onClick={() => setPalette(true)} className="sm:hidden p-2 rounded-lg hover:bg-muted"><Search size={19}/></button><button data-testid="button-theme" aria-label="Toggle theme" onClick={() => setDark(!dark)} className="p-2.5 rounded-xl hover:bg-muted interactive">{dark ? <Sun size={18}/> : <Moon size={18}/>}</button><div className="relative"><button data-testid="button-notifications" aria-label="Notifications" onClick={() => setNotifications(!notifications)} className="p-2.5 rounded-xl hover:bg-muted relative"><Bell size={18}/><span className="absolute top-2 right-2 size-1.5 bg-accent rounded-full ring-2 ring-background"/></button>{notifications && <NotificationPanel onClose={() => setNotifications(false)} />}</div><div className="hidden sm:flex items-center gap-2.5 pl-2 border-l border-border"><div className="size-9 rounded-full bg-primary/15 text-primary flex items-center justify-center text-xs font-bold">PS</div><div className="text-left"><div className="text-sm font-semibold leading-none">Priya Shah</div><div className="text-[11px] text-muted-foreground mt-1">Administrator</div></div><ChevronDown size={14} className="text-muted-foreground"/></div></div>
       </header>
       {/* @ts-ignore StudentsPage also accepts the optional voice draft bridge. */}
       <div className="flex-1 overflow-auto"><Switch><Route path="/"><Dashboard students={students} projects={projects} activities={activities} /></Route><Route path="/dashboard"><Dashboard students={students} projects={projects} activities={activities} /></Route><Route path="/students"><StudentsPage students={students} setStudents={updateStudents} flash={flash} voiceListening={listening} onVoice={startVoice} voiceDraft={voiceDraft} /></Route><Route path="/students/:id"><StudentProfile students={students} /></Route><Route path="/attendance"><AttendancePage students={students} flash={flash} /></Route><Route path="/projects"><ProjectsPage projects={projects} /></Route><Route path="/projects/:id"><ProjectDetail projects={projects} /></Route><Route path="/assignments"><ManagementPage kind="assignments" assignments={assignments} flash={flash} /></Route><Route path="/exams"><ExamsPage exams={exams} /></Route><Route path="/timetable"><Timetable /></Route><Route path="/messages"><Messages /></Route><Route path="/events"><Events events={seedEvents} /></Route><Route path="/reports"><Reports /></Route><Route path="/settings"><SettingsPage dark={dark} setDark={setDark} /></Route><Route component={NotFound} /></Switch></div>
    </main>
    {palette && <CommandPalette query={query} setQuery={setQuery} results={quickResults} onClose={() => { setPalette(false); setQuery(''); }} onVoice={startVoice} listening={listening} />}
    {toast && <div role="status" data-testid="status-toast" className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 bg-sidebar text-sidebar-foreground px-4 py-3 rounded-xl shadow-xl text-sm flex items-center gap-2 animate-in"><Check size={16} className="text-sidebar-primary"/>{toast}</div>}
  </div>;
}
function NavItem({ href, label, icon: Icon, current, onClick }: any) { const active = href === '/dashboard' ? current === '/dashboard' || current === '/' : current.startsWith(href); return <Link href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ','-')}`} onClick={onClick} className={`group flex items-center gap-3 px-3 py-2.5 rounded-xl text-sm transition-all ${active ? 'bg-sidebar-accent text-sidebar-foreground font-semibold shadow-sm' : 'text-sidebar-foreground/65 hover:text-sidebar-foreground hover:bg-sidebar-accent/70'}`}><Icon size={17} strokeWidth={active ? 2.2 : 1.8}/><span>{label}</span>{label === 'Messages' && <span className="ml-auto text-[10px] bg-sidebar-primary text-sidebar-primary-foreground rounded-full px-1.5 py-0.5">4</span>}</Link>; }
function NotificationPanel({ onClose }: { onClose: () => void }) { return <div data-testid="panel-notifications" className="absolute right-0 top-12 w-[320px] max-w-[calc(100vw-2rem)] card-surface rounded-2xl p-4 shadow-xl z-30 bg-card"><div className="flex items-center justify-between mb-3"><h3 className="font-bold">Notifications</h3><button aria-label="Close notifications" data-testid="button-close-notifications" onClick={onClose} className="text-muted-foreground hover:text-foreground"><X size={16}/></button></div><div className="space-y-3">{[['Deadline approaching','Solar study pavilion is due in 3 days.','accent'],['Attendance dip','BCA Semester 4 is below 80% this week.','primary'],['New submission','Anjali Menon uploaded HCI audit.','secondary']].map(([a,b,c],i) => <div key={a} className="flex gap-3 text-sm"><div className={`size-2 rounded-full mt-1.5 bg-${c}`}/><div><div className="font-semibold">{a}</div><div className="text-muted-foreground text-xs mt-0.5">{b}</div><div className="text-[10px] text-muted-foreground mt-1">{i+1}h ago</div></div></div>)}</div><button data-testid="button-view-all-notifications" onClick={() => { onClose(); }} className="w-full mt-4 pt-3 border-t text-xs text-primary font-semibold">Mark all as read</button></div>; }
function CommandPalette({ query, setQuery, results, onClose, onVoice, listening }: any) { const [, setLocation] = useLocation(); return <div className="fixed inset-0 z-50 bg-foreground/30 backdrop-blur-sm flex items-start justify-center pt-[12vh] px-4" onMouseDown={e => e.currentTarget === e.target && onClose()}><div className="w-full max-w-xl card-surface bg-card rounded-2xl shadow-2xl overflow-hidden stagger-in"><div className="flex items-center gap-3 px-4 h-14 border-b"><Search size={18} className="text-muted-foreground"/><input autoFocus data-testid="input-global-search" value={query} onChange={e => setQuery(e.target.value)} placeholder="Search students, projects, assignments…" className="flex-1 bg-transparent outline-none text-sm"/><button data-testid="button-voice-search" aria-label="Voice search" onClick={onVoice} className={`p-2 rounded-lg ${listening ? 'bg-accent/20 text-accent' : 'hover:bg-muted'}`}>{listening ? <MicOff size={18}/> : <Mic size={18}/>}</button><kbd className="font-mono text-[10px] text-muted-foreground border rounded px-1.5 py-1">ESC</kbd></div>{listening && <div className="px-4 py-3 bg-accent/10 text-accent text-xs flex items-center gap-2"><span className="size-2 rounded-full bg-accent animate-pulse"/> Listening — say “add student Anjali Menon BCA semester 4”</div>}<div className="p-2 max-h-[390px] overflow-auto">{query && !results.length ? <div className="p-8 text-center text-sm text-muted-foreground">No matches yet. Try a student name or course.</div> : results.length ? results.map((r: any) => <button key={r.label} data-testid={`result-search-${r.label}`} onClick={() => { setLocation(r.href); onClose(); }} className="w-full flex items-center gap-3 px-3 py-3 text-left rounded-xl hover:bg-muted interactive"><div className="size-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center"><r.icon size={16}/></div><div><div className="text-sm font-semibold">{r.label}</div><div className="text-xs text-muted-foreground">{r.sub}</div></div><ChevronRight size={15} className="ml-auto text-muted-foreground"/></button>) : <div className="p-5"><div className="text-[10px] uppercase tracking-[.16em] text-muted-foreground font-bold mb-3">Quick actions</div><div className="grid grid-cols-2 gap-2"><button data-testid="quick-add-student" onClick={() => { setLocation('/students'); onClose(); }} className="text-left p-3 rounded-xl bg-muted hover:bg-primary/10"><Plus size={16} className="text-primary mb-2"/><div className="text-sm font-semibold">Add a student</div><div className="text-xs text-muted-foreground">Create a new record</div></button><button data-testid="quick-open-attendance" onClick={() => { setLocation('/attendance'); onClose(); }} className="text-left p-3 rounded-xl bg-muted hover:bg-primary/10"><Check size={16} className="text-primary mb-2"/><div className="text-sm font-semibold">Mark attendance</div><div className="text-xs text-muted-foreground">Open today’s register</div></button></div></div>}</div></div></div>; }

function PageFrame({ eyebrow, title, subtitle, actions, children }: { eyebrow?: string; title: string; subtitle?: string; actions?: ReactNode; children: ReactNode }) { return <div className="max-w-[1440px] mx-auto px-4 sm:px-7 lg:px-10 py-8 sm:py-10"><div className="flex flex-col sm:flex-row sm:items-end justify-between gap-5 mb-8"><div><div className="text-[10px] uppercase tracking-[.18em] font-bold text-primary mb-2">{eyebrow || 'Eastbridge workspace'}</div><h2 className="text-3xl sm:text-[38px] font-bold tracking-[-.04em]">{title === 'Good morning, Priya' ? 'Hi, Faseela, Welcome Back!' : title}</h2>{subtitle && <p className="text-muted-foreground mt-2 max-w-xl">{subtitle === 'Here’s the pulse of Eastbridge. 4 items need your attention.' ? 'Here’s what’s happening with your students today.' : subtitle}</p>}</div>{actions && <div className="flex items-center gap-2 shrink-0">{actions}</div>}</div>{children}</div>; }
function Btn({ children, onClick, variant='primary', icon: Icon, testId, disabled=false }: any) { return <button disabled={disabled} data-testid={testId} onClick={onClick} className={`focus-ring interactive inline-flex items-center justify-center gap-2 rounded-xl px-3.5 h-10 text-sm font-semibold disabled:opacity-50 disabled:pointer-events-none ${variant === 'primary' ? 'bg-primary text-primary-foreground hover:brightness-105' : variant === 'soft' ? 'bg-primary/10 text-primary hover:bg-primary/15' : variant === 'danger' ? 'bg-destructive/10 text-destructive hover:bg-destructive/15' : 'border bg-card hover:bg-muted'}`}>{Icon && <Icon size={16}/>} {children}</button>; }
function Stat({ label, value, note, trend, accent='primary', icon: Icon }: any) { return <div className="card-surface rounded-2xl p-5 min-w-0 interactive"><div className="flex items-start justify-between"><div className="text-xs font-semibold text-muted-foreground">{label}</div><div className={`size-9 rounded-xl flex items-center justify-center bg-${accent}/10 text-${accent}`}><Icon size={17}/></div></div><div data-testid={`stat-${label.replaceAll(' ','-').toLowerCase()}`} className="font-mono text-3xl font-bold tracking-tight mt-4">{value}</div><div className="flex items-center gap-2 mt-2 text-xs"><span className="text-primary font-semibold">{trend}</span><span className="text-muted-foreground">{note}</span></div></div>; }
function Dashboard({ students, projects, activities }: { students: Student[]; projects: Project[]; activities: Activity[] }) { const [range, setRange] = useState('This week'); const attendanceData = [{n:'Mon',v:89},{n:'Tue',v:91},{n:'Wed',v:86},{n:'Thu',v:93},{n:'Fri',v:88},{n:'Sat',v:78}]; return <PageFrame eyebrow="Tuesday, 08 April 2025" title="Good morning, Priya" subtitle="Here’s the pulse of Eastbridge. 4 items need your attention." actions={<><Btn variant="soft" icon={Download} testId="button-dashboard-export" onClick={() => {}}>Export view</Btn><Btn icon={Plus} testId="button-dashboard-add" onClick={() => {}}>Quick add</Btn></>}><div className="grid grid-cols-2 xl:grid-cols-4 gap-3 sm:gap-4 mb-5"><Stat label="Total students" value="1,284" trend="+4.8%" note="vs last semester" accent="primary" icon={Users}/><Stat label="Today’s attendance" value="88.6%" trend="+2.1%" note="vs last Tuesday" accent="accent" icon={Check}/><Stat label="Active projects" value="42" trend="7 due soon" note="next 14 days" accent="primary" icon={FolderKanban}/><Stat label="Open assignments" value="18" trend="3 reviewing" note="across 6 courses" accent="accent" icon={ClipboardList}/></div><div className="grid lg:grid-cols-[1.5fr_1fr] gap-5"><div className="card-surface rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between mb-5"><div><h3 className="font-bold text-lg">Attendance rhythm</h3><p className="text-xs text-muted-foreground mt-1">Daily presence across campus</p></div><select data-testid="select-attendance-range" value={range} onChange={e => setRange(e.target.value)} className="bg-muted border-0 rounded-lg px-2 py-1.5 text-xs font-semibold outline-none"><option>This week</option><option>Last week</option><option>This month</option></select></div><div className="h-[220px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={attendanceData}><CartesianGrid vertical={false} stroke="hsl(var(--border))" strokeDasharray="4 4"/><XAxis dataKey="n" tickLine={false} axisLine={false} tick={{fontSize:11,fill:'hsl(var(--muted-foreground))'}}/><YAxis domain={[70,100]} tickLine={false} axisLine={false} tick={{fontSize:11,fill:'hsl(var(--muted-foreground))'}} tickFormatter={v => `${v}%`}/><ChartTooltip contentStyle={{borderRadius:12,border:'1px solid hsl(var(--border))',background:'hsl(var(--card))',fontSize:12}}/><Line type="monotone" dataKey="v" stroke={teal} strokeWidth={3} dot={{r:4,fill:orange,strokeWidth:2,stroke:'hsl(var(--card))'}} activeDot={{r:6}}/></LineChart></ResponsiveContainer></div></div><div className="card-surface rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between mb-5"><div><h3 className="font-bold text-lg">Needs attention</h3><p className="text-xs text-muted-foreground mt-1">The four things worth a look</p></div><Link href="/students" data-testid="link-view-students" className="text-xs font-bold text-primary">View all</Link></div><div className="space-y-3">{[{t:'Attendance below 80%',s:'8 students · Computer Applications',c:'accent',link:'/attendance'},{t:'Projects due this week',s:'3 projects · 2 need review',c:'primary',link:'/projects'},{t:'Unreviewed submissions',s:'14 assignments · oldest 2 days',c:'accent',link:'/assignments'},{t:'Exam grades pending',s:'Midterm · 184 students',c:'primary',link:'/exams'}].map(x => <Link href={x.link} key={x.t} data-testid={`link-attention-${x.t}`} className="flex items-center gap-3 p-3 rounded-xl hover:bg-muted interactive"><div className={`size-2 rounded-full bg-${x.c}`}/><div className="min-w-0"><div className="text-sm font-semibold truncate">{x.t}</div><div className="text-xs text-muted-foreground truncate mt-0.5">{x.s}</div></div><ChevronRight size={15} className="ml-auto text-muted-foreground shrink-0"/></Link>)}</div></div></div><div className="grid lg:grid-cols-[1.1fr_1fr] gap-5 mt-5"><div className="card-surface rounded-2xl p-5 sm:p-6"><div className="flex justify-between items-center mb-5"><div><h3 className="font-bold text-lg">Upcoming deadlines</h3><p className="text-xs text-muted-foreground mt-1">Stay ahead of the next handoffs</p></div><Link href="/projects" data-testid="link-all-deadlines" className="text-xs font-bold text-primary">See calendar</Link></div><div className="space-y-4">{projects.slice(0,4).map((p,i) => <div key={p.id} className="flex items-center gap-3"><div className="size-10 rounded-xl bg-secondary flex flex-col items-center justify-center text-secondary-foreground"><span className="font-mono text-[10px] font-bold">{['APR','APR','APR','APR'][i]}</span><span className="font-mono text-sm font-bold">{[12,16,18,22][i]}</span></div><div className="min-w-0 flex-1"><div className="text-sm font-semibold truncate">{p.name}</div><div className="text-xs text-muted-foreground mt-0.5">{p.student} · {p.type}</div></div><div className="w-20"><div className="text-right font-mono text-[10px] text-muted-foreground mb-1">{p.progress}%</div><div className="h-1.5 bg-muted rounded-full overflow-hidden"><div className="h-full bg-primary rounded-full" style={{width:`${p.progress}%`}}/></div></div></div>)}</div></div><div className="card-surface rounded-2xl p-5 sm:p-6"><div className="flex justify-between items-center mb-5"><div><h3 className="font-bold text-lg">Recent activity</h3><p className="text-xs text-muted-foreground mt-1">What changed while you were away</p></div><Link href="/messages" data-testid="link-activity" className="text-xs font-bold text-primary">Activity log</Link></div><div className="space-y-4">{activities.map((a,i) => <div key={a.text} className="flex gap-3"><div className={`size-8 rounded-lg flex items-center justify-center ${i%2 ? 'bg-primary/10 text-primary' : 'bg-accent/15 text-accent'}`}><ActivityIcon size={15}/></div><div><div className="text-sm font-medium">{a.text}</div><div className="text-xs text-muted-foreground mt-1">{a.time}</div></div></div>)}</div></div></div></PageFrame>; }

function StudentsPage({ students, setStudents, flash, voiceListening, onVoice }: { students: Student[]; setStudents: (x: Student[]) => void; flash: (s:string) => void; voiceListening:boolean; onVoice: () => void }) {
  const [search, setSearch] = useState(''); const [filter, setFilter] = useState('All'); const [sort, setSort] = useState<'name'|'performance'>('name'); const [page, setPage] = useState(1); const [selected, setSelected] = useState<number[]>([]); const [editing, setEditing] = useState<Student | null>(null); const [showForm, setShowForm] = useState(false);
  const filtered = useMemo(() => students.filter(s => (filter === 'All' || s.course === filter) && `${s.name} ${s.email} ${s.department}`.toLowerCase().includes(search.toLowerCase())).sort((a,b) => sort === 'name' ? a.name.localeCompare(b.name) : b.performance-a.performance), [students, filter, search, sort]); const pages = Math.max(1, Math.ceil(filtered.length/8)); const shown = filtered.slice((page-1)*8,page*8); const toggle = (id:number) => setSelected(s => s.includes(id) ? s.filter(x => x!==id) : [...s,id]);
  const remove = (id:number) => { if (confirm('Delete this student record?')) { setStudents(students.filter(s => s.id !== id)); flash('Student record deleted'); } };
  const add = (draft: Partial<Student>) => { const s:Student = { id:Math.max(...students.map(x=>x.id),0)+1, name:draft.name || 'New student', email:draft.email || '', phone:draft.phone || '', department:draft.department || 'Computer Applications', course:draft.course || 'BCA', semester:Number(draft.semester)||1, batch:'2025–29', attendance:100, projects:0, performance:0, status:'Active', avatar:(draft.name||'NS').split(' ').map(x=>x[0]).join('').slice(0,2), enrollmentDate:'2025-04-08' }; setStudents([s,...students]); flash('Student added to the directory'); setShowForm(false); };
  return <PageFrame eyebrow="People & records" title="Students" subtitle="A living directory of 1,284 learners, their progress, and their context." actions={<><Btn variant="soft" icon={Download} testId="button-export-students" onClick={() => flash('Student directory exported as CSV')}>Export CSV</Btn><Btn icon={Plus} testId="button-add-student" onClick={() => setShowForm(true)}>Add student</Btn></>}><div className="card-surface rounded-2xl overflow-hidden"><div className="p-4 sm:p-5 flex flex-col lg:flex-row gap-3 justify-between border-b"><div className="flex items-center gap-2 flex-1"><div className="relative flex-1 max-w-md"><Search size={16} className="absolute left-3 top-3 text-muted-foreground"/><input data-testid="input-student-search" value={search} onChange={e => {setSearch(e.target.value);setPage(1)}} placeholder="Search by name, email, department…" className="h-10 w-full bg-muted/70 rounded-xl pl-9 pr-3 text-sm outline-none focus:ring-2 ring-primary/20"/></div><button data-testid="button-voice-add" aria-label="Voice add student" onClick={onVoice} className={`h-10 px-3 rounded-xl border text-xs font-semibold ${voiceListening ? 'bg-accent/15 text-accent border-accent/30' : 'hover:bg-muted'}`}>{voiceListening ? <MicOff size={16}/> : <Mic size={16}/>}</button></div><div className="flex items-center gap-2"><div className="relative"><SlidersHorizontal size={14} className="absolute left-3 top-3 text-muted-foreground"/><select data-testid="select-student-filter" value={filter} onChange={e => {setFilter(e.target.value);setPage(1)}} className="h-10 pl-8 pr-8 rounded-xl bg-muted/70 text-sm outline-none appearance-none"><option>All</option>{courses.map(c=><option key={c}>{c}</option>)}</select></div><select data-testid="select-student-sort" value={sort} onChange={e=>setSort(e.target.value as any)} className="h-10 px-3 rounded-xl bg-muted/70 text-sm outline-none"><option value="name">Sort: name</option><option value="performance">Sort: performance</option></select></div></div>{selected.length > 0 && <div className="px-5 py-2.5 bg-primary/8 text-sm flex items-center gap-3"><span className="font-semibold">{selected.length} selected</span><button data-testid="button-bulk-export" onClick={()=>flash(`${selected.length} records exported`)} className="text-primary font-semibold text-xs">Export selected</button><button data-testid="button-clear-selection" onClick={()=>setSelected([])} className="ml-auto text-muted-foreground"><X size={15}/></button></div>}<div className="overflow-x-auto scrollbar-thin"><table className="w-full text-sm min-w-[820px]"><thead><tr className="text-left text-[11px] uppercase tracking-wider text-muted-foreground border-b bg-muted/30"><th className="p-4 w-10"><input aria-label="Select all students" data-testid="checkbox-select-all" type="checkbox" checked={shown.length>0&&shown.every(s=>selected.includes(s.id))} onChange={e=>setSelected(e.target.checked ? [...new Set([...selected,...shown.map(s=>s.id)])] : selected.filter(id=>!shown.some(s=>s.id===id)))} className="accent-primary"/></th><th className="p-4">Student</th><th className="p-4">Course</th><th className="p-4">Attendance</th><th className="p-4">Performance</th><th className="p-4">Status</th><th className="p-4 text-right">Actions</th></tr></thead><tbody>{shown.map(s=><tr key={s.id} data-testid={`row-student-${s.id}`} className="border-b last:border-0 hover:bg-muted/30 transition-colors"><td className="p-4"><input aria-label={`Select ${s.name}`} data-testid={`checkbox-student-${s.id}`} type="checkbox" checked={selected.includes(s.id)} onChange={()=>toggle(s.id)} className="accent-primary"/></td><td className="p-4"><Link href={`/students/${s.id}`} data-testid={`link-student-${s.id}`} className="flex items-center gap-3 group"><div className="size-9 rounded-xl bg-primary/10 text-primary flex items-center justify-center text-xs font-bold">{s.avatar}</div><div><div className="font-semibold group-hover:text-primary transition-colors">{s.name}</div><div className="text-xs text-muted-foreground">{s.email}</div></div></Link></td><td className="p-4"><div className="font-medium">{s.course}</div><div className="text-xs text-muted-foreground">Semester {s.semester}</div></td><td className="p-4"><div className="font-mono text-xs">{s.attendance}%</div><div className="h-1.5 w-20 bg-muted rounded-full mt-1 overflow-hidden"><div className={`h-full rounded-full ${s.attendance<80?'bg-accent':'bg-primary'}`} style={{width:`${s.attendance}%`}}/></div></td><td className="p-4 font-mono text-xs">{s.performance}/100</td><td className="p-4"><StatusPill status={s.status}/></td><td className="p-4"><div className="flex justify-end gap-1"><button aria-label={`Edit ${s.name}`} data-testid={`button-edit-student-${s.id}`} onClick={()=>{setEditing(s);setShowForm(true)}} className="p-2 rounded-lg text-muted-foreground hover:bg-muted hover:text-foreground"><Pencil size={15}/></button><button aria-label={`Delete ${s.name}`} data-testid={`button-delete-student-${s.id}`} onClick={()=>remove(s.id)} className="p-2 rounded-lg text-muted-foreground hover:bg-destructive/10 hover:text-destructive"><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div><div className="p-4 flex items-center justify-between text-xs text-muted-foreground"><span>Showing {filtered.length ? (page-1)*8+1 : 0}–{Math.min(page*8,filtered.length)} of {filtered.length} records</span><div className="flex gap-1"><button aria-label="Previous page" data-testid="button-prev-page" disabled={page===1} onClick={()=>setPage(page-1)} className="p-2 border rounded-lg disabled:opacity-40"><ChevronLeft size={15}/></button><span className="px-3 py-2 font-mono">{page} / {pages}</span><button aria-label="Next page" data-testid="button-next-page" disabled={page===pages} onClick={()=>setPage(page+1)} className="p-2 border rounded-lg disabled:opacity-40"><ChevronRight size={15}/></button></div></div></div>{showForm && <StudentForm student={editing} onClose={()=>{setShowForm(false);setEditing(null)}} onSave={draft=>{if(editing){setStudents(students.map(s=>s.id===editing.id?{...s,...draft,semester:Number(draft.semester)||s.semester}:s));flash('Student details updated');setShowForm(false);setEditing(null)}else add(draft)}}/>}</PageFrame>;
}
function StatusPill({ status }: { status:string }) { const tone = status === 'Active' || status === 'On track' || status === 'Present' || status === 'Published' ? 'primary' : status === 'At risk' || status === 'Needs review' || status === 'Late' ? 'accent' : 'muted'; return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold bg-${tone}/10 text-${tone}`}><span className={`size-1.5 rounded-full bg-${tone}`}/>{status}</span>; }
function StudentForm({ student, onClose, onSave }: { student:Student|null; onClose:()=>void; onSave:(s:Partial<Student>)=>void }) { const [draft,setDraft]=useState<Partial<Student>>(student||{}); const set=(k:string,v:string)=>setDraft({...draft,[k]:v}); return <Modal title={student ? 'Edit student' : 'Add student'} onClose={onClose}><div className="grid sm:grid-cols-2 gap-4"><Field label="Full name" value={draft.name||''} onChange={v=>set('name',v)} testId="input-student-name"/><Field label="Email" value={draft.email||''} onChange={v=>set('email',v)} testId="input-student-email"/><Field label="Phone" value={draft.phone||''} onChange={v=>set('phone',v)} testId="input-student-phone"/><label className="text-sm font-semibold">Course<select data-testid="select-form-course" value={draft.course||'BCA'} onChange={e=>set('course',e.target.value)} className="mt-1.5 w-full h-10 rounded-xl bg-muted px-3 outline-none font-normal">{courses.map(c=><option key={c}>{c}</option>)}</select></label><label className="text-sm font-semibold">Semester<input data-testid="input-student-semester" type="number" min="1" max="8" value={draft.semester||1} onChange={e=>set('semester',e.target.value)} className="mt-1.5 w-full h-10 rounded-xl bg-muted px-3 outline-none font-normal"/></label><label className="text-sm font-semibold">Department<select data-testid="select-form-department" value={draft.department||departments[0]} onChange={e=>set('department',e.target.value)} className="mt-1.5 w-full h-10 rounded-xl bg-muted px-3 outline-none font-normal">{departments.map(d=><option key={d}>{d}</option>)}</select></label></div><div className="flex justify-end gap-2 mt-7"><Btn variant="ghost" onClick={onClose} testId="button-cancel-student">Cancel</Btn><Btn onClick={()=>onSave(draft)} testId="button-save-student">{student?'Save changes':'Add student'}</Btn></div></Modal>; }
function Field({label,value,onChange,testId}:{label:string;value:string;onChange:(v:string)=>void;testId:string}) { return <label className="text-sm font-semibold">{label}<input data-testid={testId} value={value} onChange={e=>onChange(e.target.value)} className="mt-1.5 w-full h-10 rounded-xl bg-muted px-3 outline-none font-normal focus:ring-2 ring-primary/20"/></label>; }
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:ReactNode}) { return <div className="fixed inset-0 z-50 bg-foreground/35 backdrop-blur-sm flex items-center justify-center p-4" onMouseDown={e=>e.currentTarget===e.target&&onClose()}><div className="card-surface bg-card rounded-2xl w-full max-w-lg shadow-2xl stagger-in"><div className="flex items-center justify-between p-5 border-b"><h3 className="text-lg font-bold">{title}</h3><button aria-label="Close dialog" data-testid="button-close-dialog" onClick={onClose} className="p-2 rounded-lg hover:bg-muted"><X size={17}/></button></div><div className="p-5">{children}</div></div></div>; }

function StudentProfile({ students }: {students:Student[]}) { const [,params]=useRoute('/students/:id'); const student=students.find(s=>s.id===Number(params?.id))||students[0]; const [tab,setTab]=useState('Overview'); const tabs=['Overview','Attendance','Projects','Assignments','Exams','Documents']; return <PageFrame eyebrow="Students / profile" title={student.name} subtitle={`${student.course} · Semester ${student.semester} · ${student.batch}`} actions={<><Btn variant="soft" icon={MessageSquare} testId="button-message-student" onClick={()=>{}}>Message</Btn><Btn icon={Pencil} testId="button-edit-profile" onClick={()=>{}}>Edit profile</Btn></>}><div className="flex items-center gap-4 mb-7"><div className="size-16 rounded-2xl bg-primary text-primary-foreground flex items-center justify-center text-xl font-bold">{student.avatar}</div><div><div className="flex items-center gap-2"><StatusPill status={student.status}/><span className="text-xs text-muted-foreground">Joined {student.enrollmentDate}</span></div><div className="text-sm text-muted-foreground mt-2">{student.email} · {student.phone}</div></div></div><div className="flex gap-1 overflow-x-auto border-b mb-6">{tabs.map(t=><button key={t} data-testid={`tab-student-${t.toLowerCase()}`} onClick={()=>setTab(t)} className={`px-4 py-3 text-sm font-semibold whitespace-nowrap border-b-2 ${tab===t?'text-primary border-primary':'text-muted-foreground border-transparent hover:text-foreground'}`}>{t}</button>)}</div>{tab==='Overview' && <><div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5"><Stat label="Attendance" value={`${student.attendance}%`} trend={student.attendance>80?'+3.4%':'Needs care'} note="this semester" icon={Check}/><Stat label="Performance" value={`${student.performance}`} trend="Top 24%" note="course average" icon={TrendingUp}/><Stat label="Projects" value={student.projects} trend="2 active" note="in progress" icon={FolderKanban}/><Stat label="Credits earned" value="72" trend="On track" note="of 120 credits" icon={GraduationCap}/></div><div className="grid lg:grid-cols-2 gap-5"><div className="card-surface rounded-2xl p-5"><h3 className="font-bold mb-4">Academic snapshot</h3><div className="space-y-4">{[['Design systems','89','primary'],['Research methods','82','primary'],['Communication','78','accent'],['Technical studio','94','primary']].map(([x,v,c])=><div key={x}><div className="flex justify-between text-sm mb-1.5"><span>{x}</span><span className="font-mono text-xs">{v}/100</span></div><div className="h-2 bg-muted rounded-full"><div className={`h-full bg-${c} rounded-full`} style={{width:`${v}%`}}/></div></div>)}</div></div><div className="card-surface rounded-2xl p-5"><h3 className="font-bold mb-4">Advisor notes</h3><div className="p-4 rounded-xl bg-accent/10 border border-accent/20 text-sm leading-relaxed">An engaged learner with strong studio work. Check in before the next review to unblock the research handoff.</div><div className="text-xs text-muted-foreground mt-3">Added by Megha Menon · 3 days ago</div></div></div></>}{tab!=='Overview' && <div className="card-surface rounded-2xl p-8 text-center"><div className="size-12 bg-primary/10 text-primary rounded-2xl mx-auto flex items-center justify-center mb-4">{tab==='Attendance'?<Check size={22}/>:tab==='Projects'?<FolderKanban size={22}/>:tab==='Documents'?<FileText size={22}/>:<BookOpen size={22}/>}</div><h3 className="font-bold">{tab} for {student.name}</h3><p className="text-muted-foreground text-sm mt-2">{tab==='Documents'?'No new documents uploaded this week.':'This view is up to date with the latest academic records.'}</p></div>}</PageFrame>; }

function AttendancePage({students,flash}:{students:Student[];flash:(s:string)=>void}) { const [rows,setRows]=useState<Attendance[]>(()=>loadLocal('attendance',seedAttendance)); const [course,setCourse]=useState('All'); const setStatus=(name:string,status:Attendance['status'])=>{const next=rows.map(r=>r.student===name?{...r,status}:r);setRows(next);saveLocal('attendance',next);flash(`${name} marked ${status.toLowerCase()}`)}; const filtered=rows.filter(r=>course==='All'||students.find(s=>s.name===r.student)?.course===course); return <PageFrame eyebrow="Daily register" title="Attendance" subtitle="Tuesday, 08 April · Mark presence in a few taps, then spot the patterns." actions={<><Btn variant="soft" icon={Download} testId="button-export-attendance" onClick={()=>flash('Attendance report exported')}>Export report</Btn><Btn icon={Check} testId="button-save-attendance" onClick={()=>flash('Attendance saved for 08 April')}>Save register</Btn></>}><div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5"><Stat label="Present today" value="1,137" trend="88.6%" note="of 1,284 students" icon={Check}/><Stat label="Late arrivals" value="42" trend="3.3%" note="needs follow-up" accent="accent" icon={ActivityIcon}/><Stat label="Absent today" value="105" trend="-8.2%" note="vs last Tuesday" accent="accent" icon={X}/><Stat label="Best attendance" value="B.Des" trend="94.1%" note="this week" icon={TrendingUp}/></div><div className="card-surface rounded-2xl overflow-hidden"><div className="p-4 sm:p-5 border-b flex flex-col sm:flex-row gap-3 justify-between"><div><h3 className="font-bold">Today’s register</h3><p className="text-xs text-muted-foreground mt-1">Statuses update instantly and stay saved on this device.</p></div><select data-testid="select-attendance-course" value={course} onChange={e=>setCourse(e.target.value)} className="h-10 rounded-xl bg-muted px-3 text-sm outline-none"><option>All</option>{courses.map(c=><option key={c}>{c}</option>)}</select></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-sm"><thead className="text-[11px] uppercase tracking-wider text-muted-foreground bg-muted/30"><tr><th className="p-4 text-left">Student</th><th className="p-4 text-left">Course</th><th className="p-4 text-left">This term</th><th className="p-4 text-left">Today</th></tr></thead><tbody>{filtered.slice(0,12).map(r=>{const s=students.find(x=>x.name===r.student)!;return <tr key={r.student} className="border-t hover:bg-muted/30"><td className="p-4 font-semibold">{r.student}</td><td className="p-4 text-muted-foreground">{s?.course} · Sem {s?.semester}</td><td className="p-4"><span className="font-mono text-xs">{r.percentage}%</span></td><td className="p-4"><div className="flex gap-1.5">{(['Present','Late','Absent'] as Attendance['status'][]).map(st=><button key={st} data-testid={`button-attendance-${s?.id}-${st.toLowerCase()}`} onClick={()=>setStatus(r.student,st)} className={`px-3 py-1.5 rounded-lg text-xs font-semibold border ${r.status===st?(st==='Present'?'bg-primary text-primary-foreground border-primary':st==='Late'?'bg-accent text-accent-foreground border-accent':'bg-destructive text-destructive-foreground border-destructive'):'bg-card text-muted-foreground hover:bg-muted'}`}>{st}</button>)}</div></td></tr>})}</tbody></table></div></div></PageFrame>; }

function ProjectsPage({projects}:{projects:Project[]}) { const [q,setQ]=useState(''); const [status,setStatus]=useState('All'); const filtered=projects.filter(p=>(status==='All'||p.status===status)&&`${p.name} ${p.student} ${p.course}`.toLowerCase().includes(q.toLowerCase())); return <PageFrame eyebrow="Work in motion" title="Projects" subtitle="Track every capstone, studio sprint, and research handoff without losing the thread." actions={<Btn icon={Plus} testId="button-add-project" onClick={()=>{}}>New project</Btn>}><div className="flex gap-2 mb-5 overflow-x-auto"><div className="relative flex-1 max-w-sm"><Search size={16} className="absolute left-3 top-3 text-muted-foreground"/><input data-testid="input-project-search" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search projects…" className="h-10 w-full rounded-xl bg-card border pl-9 pr-3 text-sm outline-none"/></div>{['All','On track','Needs review','Completed'].map(x=><button key={x} data-testid={`button-project-filter-${x}`} onClick={()=>setStatus(x)} className={`h-10 px-3 rounded-xl text-xs font-semibold whitespace-nowrap ${status===x?'bg-primary text-primary-foreground':'bg-card border hover:bg-muted'}`}>{x}</button>)}</div><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-4">{filtered.map(p=><Link href={`/projects/${p.id}`} data-testid={`card-project-${p.id}`} key={p.id} className="card-surface rounded-2xl p-5 hover:-translate-y-1 transition-transform block"><div className="flex items-start justify-between gap-3"><div className="size-10 rounded-xl bg-secondary flex items-center justify-center text-secondary-foreground"><FolderKanban size={18}/></div><StatusPill status={p.status}/></div><h3 className="font-bold mt-5 leading-snug">{p.name}</h3><p className="text-xs text-muted-foreground mt-1">{p.student} · {p.course}</p><div className="flex justify-between text-xs mt-6 mb-2"><span className="text-muted-foreground">Progress</span><span className="font-mono font-bold">{p.progress}%</span></div><div className="h-2 bg-muted rounded-full overflow-hidden"><div className={`h-full rounded-full ${p.status==='Needs review'?'bg-accent':'bg-primary'}`} style={{width:`${p.progress}%`}}/></div><div className="flex justify-between items-center mt-5 text-xs text-muted-foreground"><span>Due {p.deadline}</span><span className="flex items-center gap-1"><UserRound size={13}/>{p.mentor}</span></div></Link>)}</div></PageFrame>; }
function ProjectDetail({projects}:{projects:Project[]}) { const [,params]=useRoute('/projects/:id'); const [progress,setProgress]=useState(projects.find(p=>p.id===Number(params?.id))?.progress||58); const project=projects.find(p=>p.id===Number(params?.id))||projects[0]; const [tab,setTab]=useState('Overview'); return <PageFrame eyebrow="Projects / detail" title={project.name} subtitle={`${project.student} · ${project.course} · ${project.type}`} actions={<><Btn variant="soft" icon={MessageSquare} testId="button-project-comment" onClick={()=>{}}>Add comment</Btn><Btn icon={Pencil} testId="button-project-edit" onClick={()=>{}}>Edit project</Btn></>}><div className="card-surface rounded-2xl p-5 sm:p-7 mb-5"><div className="flex flex-col md:flex-row justify-between gap-5"><div><StatusPill status={project.status}/><div className="text-xs text-muted-foreground mt-4">Project owner</div><div className="font-semibold mt-1">{project.student}</div></div><div className="md:w-1/2"><div className="flex justify-between text-sm font-semibold mb-2"><span>Overall progress</span><span className="font-mono">{progress}%</span></div><input aria-label="Project progress" data-testid="input-project-progress" type="range" min="0" max="100" value={progress} onChange={e=>setProgress(Number(e.target.value))} className="w-full accent-primary"/><div className="flex justify-between text-xs text-muted-foreground mt-3"><span>Started {project.startDate}</span><span>Deadline {project.deadline}</span></div></div></div></div><div className="flex gap-1 overflow-x-auto border-b mb-6">{['Overview','Timeline','Tasks','Files','Comments'].map(t=><button key={t} data-testid={`tab-project-${t.toLowerCase()}`} onClick={()=>setTab(t)} className={`px-4 py-3 text-sm font-semibold border-b-2 whitespace-nowrap ${tab===t?'border-primary text-primary':'border-transparent text-muted-foreground'}`}>{t}</button>)}</div><div className="grid lg:grid-cols-[1.2fr_.8fr] gap-5"><div className="card-surface rounded-2xl p-5"><h3 className="font-bold mb-4">{tab}</h3>{tab==='Overview'?<p className="text-sm text-muted-foreground leading-relaxed">A focused exploration of how new students navigate Eastbridge during their first week. The team is synthesizing interviews into a flexible wayfinding system for every campus building.</p>:<div className="space-y-3">{['Research synthesis','Midpoint critique','Prototype handoff','Final presentation'].map((x,i)=><div className="flex items-center gap-3 p-3 rounded-xl bg-muted/60" key={x}><div className={`size-7 rounded-lg flex items-center justify-center ${i<2?'bg-primary text-primary-foreground':'bg-card border'}`}>{i<2?<Check size={14}/>:i+1}</div><span className="text-sm font-medium">{x}</span><span className="ml-auto text-xs text-muted-foreground">{i<2?'Complete':i===2?'Apr 10':'Apr 12'}</span></div>)}</div>}</div><div className="card-surface rounded-2xl p-5"><h3 className="font-bold mb-4">Project details</h3><div className="space-y-3 text-sm">{[['Mentor',project.mentor],['Course',project.course],['Type',project.type],['Last update','Today, 09:42']].map(([a,b])=><div className="flex justify-between gap-3" key={a}><span className="text-muted-foreground">{a}</span><span className="font-semibold text-right">{b}</span></div>)}</div></div></div></PageFrame>; }

function ManagementPage({kind,assignments,flash}:{kind:string;assignments:Assignment[];flash:(s:string)=>void}) { const [q,setQ]=useState(''); const [status,setStatus]=useState('All'); const shown=assignments.filter(a=>(status==='All'||a.status===status)&&a.title.toLowerCase().includes(q.toLowerCase())); return <PageFrame eyebrow="Coursework" title="Assignments" subtitle="Deadlines, submissions, and review queues in one clear view." actions={<Btn icon={Plus} testId="button-create-assignment" onClick={()=>flash('Assignment draft created')}>Create assignment</Btn>}><div className="card-surface rounded-2xl overflow-hidden"><div className="p-4 flex flex-wrap gap-2 border-b"><div className="relative flex-1 min-w-[220px]"><Search size={15} className="absolute left-3 top-3 text-muted-foreground"/><input data-testid="input-assignment-search" value={q} onChange={e=>setQ(e.target.value)} placeholder="Find an assignment…" className="h-10 w-full rounded-xl bg-muted pl-9 pr-3 outline-none text-sm"/></div>{['All','Open','Reviewing','Closed'].map(s=><button data-testid={`button-assignment-filter-${s}`} key={s} onClick={()=>setStatus(s)} className={`h-10 px-3 rounded-xl text-xs font-semibold ${status===s?'bg-primary text-primary-foreground':'bg-muted hover:bg-secondary'}`}>{s}</button>)}</div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-sm"><thead className="text-[11px] uppercase tracking-wider text-muted-foreground bg-muted/30"><tr><th className="p-4 text-left">Assignment</th><th className="p-4 text-left">Course</th><th className="p-4 text-left">Submissions</th><th className="p-4 text-left">Deadline</th><th className="p-4 text-left">Status</th><th/></tr></thead><tbody>{shown.map(a=><tr key={a.id} className="border-t hover:bg-muted/30"><td className="p-4 font-semibold">{a.title}</td><td className="p-4 text-muted-foreground">{a.course}</td><td className="p-4"><div className="flex items-center gap-2"><div className="w-20 h-1.5 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{width:`${a.submissionRate}%`}}/></div><span className="font-mono text-xs">{a.submissionRate}%</span></div></td><td className="p-4 font-mono text-xs">{a.deadline}</td><td className="p-4"><StatusPill status={a.status}/></td><td className="p-4 text-right"><button aria-label={`More actions for ${a.title}`} data-testid={`button-assignment-more-${a.id}`} onClick={()=>flash('Assignment actions opened')} className="p-2 rounded-lg hover:bg-muted"><MoreHorizontal size={16}/></button></td></tr>)}</tbody></table></div></div></PageFrame>; }
function ExamsPage({exams}:{exams:Exam[]}) { const [selected,setSelected]=useState(exams[0]); const chart=selected.grades.map((g,i)=>({name:`Band ${i+1}`,value:g})); return <PageFrame eyebrow="Assessment" title="Exams & grades" subtitle="See what is scheduled, what is being graded, and where cohorts are landing." actions={<Btn icon={Plus} testId="button-create-exam" onClick={()=>{}}>Schedule exam</Btn>}><div className="grid lg:grid-cols-[1.2fr_.8fr] gap-5"><div className="card-surface rounded-2xl overflow-hidden"><div className="p-5 border-b"><h3 className="font-bold">Exam calendar</h3><p className="text-xs text-muted-foreground mt-1">10 assessments · spring term</p></div>{exams.map(e=><button key={e.id} data-testid={`button-exam-${e.id}`} onClick={()=>setSelected(e)} className={`w-full text-left p-4 flex items-center gap-3 border-b last:border-0 hover:bg-muted/50 ${selected.id===e.id?'bg-primary/6':''}`}><div className="size-10 rounded-xl bg-secondary flex items-center justify-center text-secondary-foreground"><BookOpen size={17}/></div><div className="min-w-0 flex-1"><div className="font-semibold text-sm truncate">{e.name}</div><div className="text-xs text-muted-foreground mt-1">{e.department} · Semester {e.semester} · {e.date}</div></div><StatusPill status={e.status}/></button>)}</div><div className="card-surface rounded-2xl p-5"><div className="flex items-center justify-between"><div><h3 className="font-bold">Performance bands</h3><p className="text-xs text-muted-foreground mt-1">{selected.subject}</p></div><TrendingUp size={18} className="text-primary"/></div><div className="h-[240px] mt-5"><ResponsiveContainer width="100%" height="100%"><BarChart data={chart} barSize={27}><CartesianGrid vertical={false} stroke="hsl(var(--border))" strokeDasharray="4 4"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:10,fill:'hsl(var(--muted-foreground))'}}/><YAxis tickLine={false} axisLine={false} tick={{fontSize:10,fill:'hsl(var(--muted-foreground))'}}/><ChartTooltip contentStyle={{borderRadius:12,border:'1px solid hsl(var(--border))',background:'hsl(var(--card))',fontSize:12}}/><Bar dataKey="value" radius={[6,6,0,0]} fill={teal}/></BarChart></ResponsiveContainer></div><div className="flex items-center justify-between border-t pt-4"><span className="text-xs text-muted-foreground">{selected.students} students</span><Btn variant="soft" testId="button-export-grades" onClick={()=>{}}>Export grades</Btn></div></div></div></PageFrame>; }

function Timetable() { const blocks=[['09:00','Design studio','B.Des · Sem 4','A-204'],['10:30','Web programming','BCA · Sem 2','Lab 03'],['12:00','Break','All cohorts','Café'],['13:30','Research methods','MCA · Sem 2','B-108'],['15:00','Systems lab','B.Tech · Sem 6','Lab 01']]; return <PageFrame eyebrow="Weekly rhythm" title="Timetable" subtitle="Week of 07 April 2025 · Keep the whole campus in view." actions={<Btn variant="soft" icon={Download} testId="button-export-timetable" onClick={()=>{}}>Export timetable</Btn>}><div className="card-surface rounded-2xl overflow-hidden"><div className="grid grid-cols-6 min-w-[720px] border-b"><div className="p-4 text-xs text-muted-foreground">IST</div>{['Mon 07','Tue 08','Wed 09','Thu 10','Fri 11'].map(d=><div key={d} className={`p-4 text-xs font-bold ${d==='Tue 08'?'text-primary bg-primary/5':''}`}>{d}</div>)}</div><div className="min-w-[720px]">{blocks.map((b,i)=><div key={b[0]} className="grid grid-cols-6 min-h-[92px] border-b last:border-0"><div className="p-4 text-xs font-mono text-muted-foreground">{b[0]}</div>{[0,1,2,3,4].map((d)=><div className="p-2 border-l" key={d}>{(d+i)%3===0&&<div className={`h-full rounded-xl p-3 ${b[1]==='Break'?'bg-accent/12':'bg-secondary'}`}><div className="text-xs font-bold">{b[1]}</div><div className="text-[10px] text-muted-foreground mt-1">{b[2]}</div><div className="text-[10px] text-primary font-semibold mt-2">{b[3]}</div></div>}</div>)}</div>)}</div></div></PageFrame>; }
function Messages() { const [active,setActive]=useState(0); const msgs=[['Admissions team','Semester registration needs a final review before Friday.','10:42','AT'],['Megha Menon','The wayfinding project is ready for midpoint critique.','09:18','MM'],['Ritesh Kumar','Could you share the BCA attendance breakdown?','Yesterday','RK'],['Exam cell','Grade publishing window opens tomorrow.','Mon','EC']]; return <PageFrame eyebrow="People, in sync" title="Messages" subtitle="A quieter place to keep decisions and requests moving." actions={<Btn icon={Plus} testId="button-compose-message" onClick={()=>{}}>New message</Btn>}><div className="card-surface rounded-2xl overflow-hidden grid lg:grid-cols-[.8fr_1.2fr] min-h-[510px]"><div className="border-r"><div className="p-4 border-b"><div className="relative"><Search size={15} className="absolute left-3 top-3 text-muted-foreground"/><input data-testid="input-message-search" placeholder="Search conversations" className="h-10 rounded-xl bg-muted w-full pl-9 text-sm outline-none"/></div></div>{msgs.map((m,i)=><button key={m[0]} data-testid={`button-message-thread-${i}`} onClick={()=>setActive(i)} className={`w-full text-left p-4 flex gap-3 border-b hover:bg-muted/50 ${active===i?'bg-primary/6':''}`}><div className="size-9 rounded-xl bg-primary/10 text-primary flex items-center justify-center text-xs font-bold">{m[3]}</div><div className="min-w-0"><div className="flex justify-between gap-2"><span className="font-semibold text-sm truncate">{m[0]}</span><span className="text-[10px] text-muted-foreground">{m[2]}</span></div><p className="text-xs text-muted-foreground mt-1 truncate">{m[1]}</p></div></button>)}</div><div className="p-5 sm:p-7 flex flex-col"><div className="flex items-center gap-3 pb-5 border-b"><div className="size-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center text-xs font-bold">{msgs[active][3]}</div><div><div className="font-bold">{msgs[active][0]}</div><div className="text-xs text-muted-foreground">Eastbridge workspace</div></div></div><div className="flex-1 py-6"><div className="max-w-md bg-muted rounded-2xl rounded-tl-sm p-4 text-sm leading-relaxed">{msgs[active][1]}<div className="text-[10px] text-muted-foreground mt-2">{msgs[active][2]}</div></div></div><div className="flex gap-2"><input data-testid="input-message-reply" placeholder="Write a reply…" className="h-11 rounded-xl bg-muted px-4 flex-1 text-sm outline-none"/><Btn testId="button-send-message" onClick={()=>{}} icon={MessageSquare}>Send</Btn></div></div></div></PageFrame>; }
function Events({events}:{events:Event[]}) { const [month,setMonth]=useState(3); return <PageFrame eyebrow="Campus calendar" title="Events" subtitle="The moments that make the academic year feel like a shared place." actions={<Btn icon={Plus} testId="button-add-event" onClick={()=>{}}>Add event</Btn>}><div className="card-surface rounded-2xl p-5 sm:p-7"><div className="flex items-center justify-between mb-7"><button data-testid="button-prev-month" onClick={()=>setMonth(month-1)} className="p-2 rounded-lg hover:bg-muted"><ChevronLeft size={18}/></button><h3 className="font-bold text-lg">April 2025</h3><button data-testid="button-next-month" onClick={()=>setMonth(month+1)} className="p-2 rounded-lg hover:bg-muted"><ChevronRight size={18}/></button></div><div className="grid grid-cols-7 gap-1 text-center text-[10px] uppercase tracking-wider text-muted-foreground mb-2">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=><div key={x} className="p-2">{x}</div>)}</div><div className="grid grid-cols-7 gap-1">{Array.from({length:35},(_,i)=>{const day=i-1;const ev=events.find(e=>Number(e.date.slice(-2))===day);return <button key={i} data-testid={`button-calendar-day-${i}`} className={`min-h-[70px] sm:min-h-[88px] p-2 text-left rounded-xl border ${day===8?'border-primary bg-primary/5':'border-transparent hover:bg-muted'} ${day<1||day>30?'opacity-30':''}`}><span className={`text-xs font-mono ${day===8?'text-primary font-bold':''}`}>{day>0&&day<=30?day:''}</span>{ev&&<div className="mt-2 text-[10px] font-semibold leading-tight text-primary">{ev.title}</div>}</button>})}</div></div></PageFrame>; }
function Reports() { const [generated,setGenerated]=useState(false); const pie=[{name:'On track',value:68},{name:'Needs review',value:19},{name:'At risk',value:13}]; return <PageFrame eyebrow="Signals & trends" title="Reports" subtitle="Turn the daily stream into a clear story for your next review." actions={<><Btn variant="soft" icon={Download} testId="button-export-report" onClick={()=>setGenerated(true)}>Export report</Btn><Btn icon={BarChart3} testId="button-generate-report" onClick={()=>setGenerated(true)}>Generate report</Btn></>}><div className="grid md:grid-cols-3 gap-4 mb-5">{[['Student health','Attendance, engagement, risk flags',Check],['Academic progress','Performance by cohort and course',TrendingUp],['Operations','Deadlines, workload, outcomes',BarChart3]].map(([a,b,I],i)=><button key={a as string} data-testid={`button-report-category-${i}`} onClick={()=>setGenerated(false)} className="card-surface text-left rounded-2xl p-5 hover:border-primary/40 interactive"><div className="size-10 rounded-xl bg-primary/10 text-primary flex items-center justify-center mb-5"><I size={18}/></div><h3 className="font-bold">{a as string}</h3><p className="text-xs text-muted-foreground mt-1">{b as string}</p><span className="inline-flex text-xs text-primary font-bold mt-5">Open report <ChevronRight size={14} className="ml-1"/></span></button>)}</div><div className="grid lg:grid-cols-[1fr_1fr] gap-5"><div className="card-surface rounded-2xl p-5"><div className="flex justify-between"><div><h3 className="font-bold">Student health mix</h3><p className="text-xs text-muted-foreground mt-1">Current term · 1,284 students</p></div>{generated&&<span className="text-[10px] text-primary font-bold flex items-center gap-1"><Check size={13}/> Ready</span>}</div><div className="h-[250px]"><ResponsiveContainer><PieChart><Pie data={pie} dataKey="value" innerRadius={65} outerRadius={92} paddingAngle={3}>{pie.map((_,i)=><Cell key={i} fill={[teal,orange,'#d65f54'][i]}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer></div><div className="space-y-2">{pie.map((p,i)=><div className="flex items-center text-sm" key={p.name}><span className="size-2 rounded-full mr-2" style={{background:[teal,orange,'#d65f54'][i]}}/>{p.name}<span className="ml-auto font-mono text-xs">{p.value}%</span></div>)}</div></div><div className="card-surface rounded-2xl p-5"><h3 className="font-bold">Report history</h3><div className="space-y-3 mt-5">{['March student health summary','Spring workload review','February attendance pulse','Semester 1 outcomes'].map((x,i)=><div className="flex items-center gap-3 p-3 bg-muted/60 rounded-xl" key={x}><FileText size={17} className="text-primary"/><div className="text-sm font-semibold flex-1">{x}<div className="text-[10px] text-muted-foreground font-normal mt-1">{i+1} {i?'weeks':'day'} ago · PDF</div></div><button aria-label={`Download ${x}`} data-testid={`button-download-report-${i}`} onClick={()=>setGenerated(true)} className="p-2 hover:bg-card rounded-lg"><Download size={15}/></button></div>)}</div></div></div></PageFrame>; }
function SettingsPage({dark,setDark}:{dark:boolean;setDark:(x:boolean)=>void}) { const [section,setSection]=useState('Profile'); const sections=['Profile','Account','Notifications','Appearance','Departments','Courses','Academic year']; return <PageFrame eyebrow="Workspace preferences" title="Settings" subtitle="Make EduManage feel like yours. Changes save automatically on this device."><div className="grid lg:grid-cols-[220px_1fr] gap-5"><div className="card-surface rounded-2xl p-2 h-fit">{sections.map(s=><button key={s} data-testid={`button-settings-${s.toLowerCase().replaceAll(' ','-')}`} onClick={()=>setSection(s)} className={`w-full text-left px-3 py-2.5 rounded-xl text-sm font-semibold ${section===s?'bg-primary text-primary-foreground':'hover:bg-muted text-muted-foreground'}`}>{s}</button>)}</div><div className="card-surface rounded-2xl p-5 sm:p-7"><h3 className="text-xl font-bold">{section}</h3><p className="text-sm text-muted-foreground mt-1 mb-7">Configure your {section.toLowerCase()} preferences.</p>{section==='Profile'?<div className="max-w-lg space-y-4"><div className="flex items-center gap-4 mb-6"><div className="size-14 rounded-2xl bg-primary text-primary-foreground flex items-center justify-center font-bold">PS</div><Btn variant="soft" icon={Upload} testId="button-upload-avatar" onClick={()=>{}}>Change photo</Btn></div><Field label="Full name" value="Priya Shah" onChange={()=>{}} testId="input-profile-name"/><Field label="Work email" value="priya.shah@eastbridge.edu" onChange={()=>{}} testId="input-profile-email"/><Field label="Role" value="Administrator" onChange={()=>{}} testId="input-profile-role"/></div>:section==='Appearance'?<div className="space-y-4 max-w-xl"><div className="flex items-center justify-between p-4 rounded-xl bg-muted"><div><div className="font-semibold">Dark interface</div><div className="text-xs text-muted-foreground mt-1">A lower-light view for late admin sessions.</div></div><button data-testid="button-settings-theme" aria-label="Toggle dark interface" onClick={()=>setDark(!dark)} className={`w-12 h-7 rounded-full p-1 transition-colors ${dark?'bg-primary':'bg-border'}`}><span className={`block size-5 bg-card rounded-full transition-transform ${dark?'translate-x-5':''}`}/></button></div><div className="p-4 rounded-xl border"><div className="font-semibold mb-3">Density</div><div className="flex gap-2"><button data-testid="button-density-comfortable" className="px-3 py-2 rounded-lg bg-primary text-primary-foreground text-xs font-semibold">Comfortable</button><button data-testid="button-density-compact" className="px-3 py-2 rounded-lg bg-muted text-xs font-semibold">Compact</button></div></div></div>:<div className="space-y-3 max-w-xl">{['Email me daily digest','Notify me about attendance dips','Show deadline reminders','Share anonymous usage analytics'].map((x,i)=><label key={x} className="flex items-center justify-between p-4 rounded-xl bg-muted cursor-pointer"><span className="text-sm font-semibold">{x}</span><input data-testid={`checkbox-setting-${i}`} type="checkbox" defaultChecked={i<3} className="size-4 accent-primary"/></label>)}</div>}</div></div></PageFrame>; }
function NotFound() { return <PageFrame eyebrow="404" title="That page wandered off." subtitle="The workspace route does not exist yet."><Link href="/dashboard" data-testid="link-back-dashboard" className="inline-flex h-10 px-4 items-center rounded-xl bg-primary text-primary-foreground text-sm font-semibold">Back to overview</Link></PageFrame>; }

export default App;